validators.conversationRef:
v.optional(
      v.object({
        conversationId: v.string(),
        messageIds: v.optional(v.array(v.string())),
      }),
    )

validators.updates:
v.object({
      status: v.optional(
        v.union(
          v.literal("active"),
          v.literal("completed"),
          v.literal("cancelled"),
          v.literal("blocked"),
        ),
      ),
      data: v.optional(v.any()),
    })

validators.participant:
v.object({
      id: v.string(),
      type: v.string(),
      joinedAt: v.number(),
    })

validators.participants:
v.optional(
      v.array(
        v.object({
          id: v.string(),
          type: v.string(), // "user", "agent", "tool", etc.
          joinedAt: v.number(),
        }),
      ),
    )

validators.add:
v.optional(
      v.array(
        v.object({
          id: v.string(),
          type: v.string(),
          joinedAt: v.number(),
        }),
      ),
    )
